create table if not exists "sync_entities" ("user_id" text not null, "collection" text not null check (collection in ('itemStore', 'favouriteCard', 'favouriteItem', 'history', 'recentView', 'subscribe', 'config')), "entity_id" text not null, "data_json" text, "data_hash" text not null, "version" text not null, "client_changed_at" integer not null, "server_updated_at" integer not null, "deleted_at" integer, "last_terminal_uuid" text not null, "last_op_id" text not null, constraint "pk_sync_entities" primary key ("user_id", "collection", "entity_id"));
create index if not exists "idx_sync_entities_user_collection" on "sync_entities" ("user_id", "collection")
